import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 6
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if not record or (len(record) == 1 and record[0] == ""):
            continue
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    def header_score(record: list[str]) -> int:
        score = 0
        for value in record:
            value = value.strip()
            if re.search(r"[A-Za-zÀ-ÖØ-öø-ÿ]", value):
                score += 1
        return score

    header_index = next(
        (
            i
            for i, record in enumerate(records)
            if len(record) == expected_width
            and header_score(record) >= (expected_width + 1) // 2
        ),
        None,
    )

    if header_index is None:
        header_index = 0

    def fit_width(record: list[str], width: int) -> list[str]:
        values = list(record)
        if len(values) > width:
            values = values[: width - 1] + [";".join(values[width - 1 :])]
        elif len(values) < width:
            values.extend([""] * (width - len(values)))
        return values

    columns = fit_width(records[header_index], expected_width)
    columns[0] = columns[0].lstrip("\ufeff")
    rows = [
        fit_width(record, expected_width)
        for record in records[header_index + 1 :]
    ]

    return {"columns": columns, "rows": rows}
